// Captured 13x13 Bridges generator seed 42. No retained solution is supplied.
// The previous native search exhausted 2,000,001 visits on this board.
export function heuristicBridge() {
  const input = `.............
...C.........
..G..........
.C..M........
.......O.B...
.G.......R...
......m......
..P.B........
....O....R...
............A
.....P.Am....
.W.....YW..M.
...Y.........
`;
  const rows = input.trim().split('\n'), chars = '.RBYGOCMmPAWgTbcp';
  return { width: 13, height: 13, input, mode: 'bridges',
    board: Array.from({ length: 13 }, (_, x) => rows.map(row => chars.indexOf(row[x]))),
    topology: { walls: [], warps: [], blocks: [], bridges: [{ x: 9, y: 10, over: 'horizontal' }] },
  };
}
